A.cs5=new B.a("C","mendorong dialog antarperwakilan pedagang untuk menyepakati etika berdagang yang menghormati kebiasaan berbeda dan kenyamanan pembeli.",!0,null,null,null)
A.cE0=new B.a("D","memisahkan lokasi pedagang pendatang dan pedagang lokal agar tidak saling mengganggu.",!1,null,null,null)
