A.bxp=new B.a("D","perbedaan latar belakang sebaiknya tidak terlalu disentuh dalam kegiatan siswa agar tidak menimbulkan risiko salah paham.",!1,null,null,null)
A.bTg=new B.a("E","keberagaman perlu diberi ruang secara proporsional dalam satu bingkai kegiatan bersama agar persatuan tidak dibangun lewat penghapusan perbedaan.",!0,null,null,null)
