A.bZx=new B.a("B",u.eZ,!1,2,null,null)
A.Wk=new B.a("C","mengurangi bantuan secara drastis agar rekan lain terpaksa belajar sendiri dan tidak terus menerus datang kepada Anda.",!1,1,null,null)
A.WH=new B.a("D","menerima saja posisi sebagai orang yang paling diandalkan karena itu menunjukkan kualitas kerja Anda memang di atas rata-rata.",!1,3,null,null)
A.Rv=new B.a("E","membantu hanya orang-orang yang menurut Anda benar-benar serius belajar agar waktu Anda tidak habis untuk persoalan yang sama.",!1,4,null,null)
