A.cuT=new B.a("D","mengubah laporan menjadi bantuan kelompok agar pemanfaatan bibit tetap sesuai tujuan pertanian.",!1,3,null,null)
A.dVg=new B.a("E","meminta penerima mengganti 15 bibit tersebut agar laporan dapat tetap sesuai daftar awal.",!1,2,null,null)
