A.hJD=s(["P13N:0","P13N:60","P13N:120","P13N:180"],t.s)
A.kmo=new B.v("P13B:0","P13B:45","+45\xb0","Dua segmen bergerak bersama 45 derajat.")
A.khb=new B.v("P13B:45","P13B:90","+45\xb0","Arah seluruh objek tetap bergeser dengan ritme yang sama.")
