A.eyN=new B.b(32,A.c,"Verbal \u2022 Analogi","Hubungan kata kurikulum : pembelajaran paling sepadan dengan hubungan ...",A.fRF,60,"Kurikulum menjadi acuan bagi pembelajaran. Hubungan yang paling sepadan adalah cetak biru yang menjadi acuan bagi pembangunan.","/skd/tiu/verbal/analogi","Menengah Atas",null)
