A.d3r=new B.a("C","membagi bantuan sama rata tanpa melihat kondisi setiap keluarga.",!1,null,null,null)
A.caa=new B.a("D","menunda pembagian sampai semua warga menyetujui daftar penerima.",!1,null,null,null)
