A.fcw=new B.b(97,A.b,"Loyal",u.L,A.huj,50,"Jawaban D paling loyal karena menjaga kerahasiaan proses internal dan nama baik instansi tanpa memberi informasi spekulatif. Loyalitas tetap harus disertai sikap profesional dan menghormati mekanisme resmi.","/skd/tkp/loyal","ELITE 01",null)
A.bpx=new B.a("A","meminta petugas lapangan tetap mengunggah data sesuai jadwal karena disiplin pelaporan harus dibangun sejak awal penerapan aplikasi.",!1,2,null,null)
A.ecy=new B.a("B","mengusulkan fitur simpan luring, batas waktu unggah setelah mendapat sinyal, dan penanda kendala jaringan agar data tetap masuk tanpa menyalahkan petugas.",!1,5,null,null)
