A.cpN=new B.a("D","pemerintah cukup melakukan sosialisasi agar orang tua memahami bahwa kamera digunakan untuk keselamatan anak dan bukan untuk mengawasi pribadi siswa.",!1,null,null,null)
A.cw_=new B.a("E","rekaman harus dihapus setiap hari kecuali jika terjadi pelanggaran lalu lintas atau insiden keselamatan di sekitar sekolah.",!1,null,null,null)
