A.ezX=new B.b(37,A.c,"Numerik","Perhatikan deret berikut.\n\n8, 15, 27, 44, 66, ...\n\nJika pola pertambahan tetap berlanjut, bilangan berikutnya adalah ...",A.fDe,60,"Selisih deret: 7, 12, 17, 22. Selisih bertambah 5, maka selisih berikutnya 27. Jadi 66 + 27 = 93. Jawaban D.","/skd/tiu/numerik","Sedang",null)
