A.dyx=new B.a("C","memberikan dana seluruhnya kepada kelompok miskin karena mereka paling membutuhkan bantuan.",!1,null,null,null)
A.cN9=new B.a("D","membagi dana sama rata agar tidak ada kelompok yang merasa dibedakan.",!1,null,null,null)
