A.enB=new B.a("C","meminta rekan mengganti selisih uang secara pribadi tanpa perlu koreksi dokumen.",!1,null,null,null)
A.dhv=new B.a("D","mengoreksi waktu sesuai fakta, menyesuaikan perhitungan hak, dan mengingatkan pentingnya ketepatan dokumen pertanggungjawaban.",!0,null,null,null)
A.dXG=new B.a("E","menunggu pemeriksa resmi menemukan kesalahan tersebut agar tidak dianggap mencari masalah.",!1,null,null,null)
A.hfI=s([A.c37,A.e_Q,A.enB,A.dhv,A.dXG],t.J)
A.ewM=new B.b(13,A.e,"Integritas","Dalam sebuah pemeriksaan internal, Anda menemukan bahwa laporan perjalanan dinas mencantumkan waktu keberangkatan lebih awal daripada waktu sebenarnya. Selisihnya tidak besar, tetapi berpengaruh pada perhitungan uang harian. Rekan Anda mengatakan praktik itu sudah biasa karena perjalanan tetap dilakukan dan tidak ada kerugian besar bagi kantor.\n\nSikap yang paling tepat adalah ...",A.hfI,55,"Integritas menuntut dokumen pertanggungjawaban sesuai fakta, meskipun selisihnya kecil. Kesalahan waktu yang memengaruhi hak pembayaran harus dikoreksi secara resmi. Opsi D paling tepat.","/skd/twk/integritas","Sulit",null)
A.cRp=new B.a("A","memberikan bantuan lebih banyak kepada warga yang aktif agar partisipasi sosial meningkat.",!1,null,null,null)
A.dxl=new B.a("B","membagi bantuan sama rata agar tidak ada warga yang merasa diperlakukan berbeda.",!1,null,null,null)
A.dUO=new B.a("C","menolak keluarga yang jarang hadir karena mereka tidak menunjukkan kepedulian terhadap lingkungan.",!1,null,null,null)
A.b9E=new B.a("D","menetapkan prioritas berdasarkan tingkat kebutuhan riil, sambil tetap memberi penghargaan sosial melalui cara lain yang tidak mengurangi hak warga rentan.",!0,null,null,null)
A.cxN=new B.a("E","menunda pembagian bantuan sampai seluruh warga aktif dalam kegiatan lingkungan.",!1,null,null,null)
A.fnr=s([A.cRp,A.dxl,A.dUO,A.b9E,A.cxN],t.J)
A.eTN=new B.b(14,A.e,"Pancasila","Dalam rapat warga, muncul usulan agar bantuan pangan diberikan lebih banyak kepada keluarga yang aktif mengikuti kegiatan lingkungan. Namun data menunjukkan ada keluarga yang jarang hadir karena merawat anggota keluarga sakit dan justru lebih membutuhkan bantuan. Sebagian warga menilai keaktifan sosial harus tetap diberi penghargaan.\n\nKeputusan yang paling sesuai dengan nilai Pancasila adalah ...",A.fnr,55,"Pancasila menempatkan kemanusiaan dan keadilan sosial sebagai dasar. Bantuan pangan harus berbasis kebutuhan riil, bukan hadiah keaktifan. Opsi D paling tepat karena tetap menghargai partisipasi tanpa mengorbankan warga rentan.","/skd/twk/pancasila","Sulit",null)
A.bGD=new B.a("A","aturan tersebut tepat karena sekolah perlu memastikan semua kewajiban administrasi dipenuhi.",!1,null,null,null)
A.biw=new B.a("B","siswa yang belum melunasi iuran sebaiknya mengikuti ujian susulan setelah pembayaran selesai.",!1,null,null,null)
A.enU=new B.a("C","sekolah bebas menentukan syarat ujian karena kegiatan internal berada di bawah kewenangannya.",!1,null,null,null)
A.drt=new B.a("D","orang tua harus bertanggung jawab penuh sehingga sekolah tidak perlu memproses keringanan.",!1,null,null,null)
A.bC4=new B.a("E","hak mengikuti ujian tidak boleh dihambat oleh persoalan iuran, terutama bagi siswa yang sedang mengajukan keringanan.",!0,null,null,null)
A.h0w=s([A.bGD,A.biw,A.enU,A.drt,A.bC4],t.J)
A.ex1=new B.b(15,A.e,"UUD 1945","Sebuah sekolah negeri menerapkan aturan bahwa siswa yang belum melunasi iuran kegiatan tidak boleh menerima kartu ujian. Beberapa siswa berasal dari keluarga kurang mampu dan sudah mengajukan keringanan, tetapi belum diproses. Pihak sekolah beralasan aturan itu diperlukan agar orang tua lebih disiplin membayar.\n\nPenilaian yang paling tepat berdasarkan prinsip hak warga negara adalah ...",A.h0w,55,"Hak memperoleh pendidikan dan mengikuti proses evaluasi tidak boleh dihambat secara tidak proporsional oleh iuran, apalagi jika ada mekanisme keringanan. Opsi E paling sesuai dengan perlindungan hak warga.","/skd/twk/uud-1945","Sulit",null)
A.dh7=new B.a("A","mengadaptasi pengetahuan global dengan memperhatikan kondisi lokal, kemampuan warga, dan kebutuhan nyata desa.",!0,null,null,null)
A.beD=new B.a("B","meniru aplikasi luar negeri karena teknologi yang sudah berhasil tidak perlu banyak diubah.",!1,null,null,null)
A.cPT=new B.a("C","menolak semua konsep dari luar negeri agar solusi benar-benar nasional.",!1,null,null,null)
A.ctK=new B.a("D","membuat aplikasi secanggih mungkin agar desa terlihat maju secara digital.",!1,null,null,null)
A.dHj=new B.a("E","menunda inovasi sampai semua desa memiliki jaringan internet yang setara.",!1,null,null,null)
