A.bSf=new B.a("C","menjelaskan bahwa status aplikasi kadang terlambat diperbarui sehingga warga tidak perlu khawatir.",!1,3,null,null)
A.cdX=new B.a("D","menyarankan warga membuat permohonan baru agar statusnya dapat dipantau dari awal.",!1,4,null,null)
